-- BEGIN GENERATED RESIDENT ROSTER (web/scripts/gen-seeds.mjs)
INSERT INTO npc_personas (slug, display_name, spawn_zone, is_permanent, persona_prompt, canned_dialogue, active, post, bio, tone, schedule, talk) VALUES
  ('wren', 'Alice', 'courtyard', TRUE, NULL, ARRAY['@morning Morning! The notice board has something new, I think. Probably.', 'Club goals are coming along. Every bit helps.', 'If you need anything, I''m usually at HQ. Or near it. Or looking for it.']::text[], TRUE, 'hq_lead', 'Keeps HQ running, more or less: club goals, the notice board, everyone''s first day. Meets every new member on the wharf.', 'warm', '{"home":"hq","dawn":["hq"],"day":["hq","plaza","path","hq","pond"],"evening":["plaza","bench"],"night":["hq","bench","hq"]}'::jsonb, '[["[happy] {name}! Good timing.","I just pinned something new on the notice board. Or I meant to. It''s in one of these pockets.","Club goals are coming along, by the way. Everything you chip in shows on the monument."],["If you ever lose track of what''s next, your Journal has it.","[surprised] Oh! And check the mailbox. Letters from HQ go there. I write most of them. Sorry about the handwriting."],["[sleepy] I was up early sorting the volunteer sign-ups.","[happy] Worth it, though. Somebody''s always building something here."]]'::jsonb),
  ('mayor', 'Mayor Eliza', 'courtyard', TRUE, NULL, ARRAY['Welcome back. The light here changes with the season, have you noticed?', 'Every board on that clubhouse was put up by someone who believed in this place.', 'If you ever want to hear how this all started, you know where to find me.']::text[], TRUE, 'villager', 'The island''s first resident and its historian. Remembers everyone''s first week and will tell the club''s story to anyone who sits still.', 'warm', '{"home":"hq","dawn":["home"],"day":["path","plaza","bench","pond"],"evening":["plaza","pond"],"night":["plaza","home"]}'::jsonb, '[["[happy] Ah, {name}. Stay a while, if you like.","This island started as one bench and an argument about where HQ should go.","We were all wrong, of course. It went exactly where it needed to be."],["Every club goal you finish, the island remembers.","[happy] The club monument grows a little each time. I check on it every morning."],["The light here changes with the seasons. Have you noticed?","[surprised] Autumn''s my favourite. The whole path goes gold."]]'::jsonb),
  ('shopkeeper', 'Toren', 'courtyard', TRUE, NULL, ARRAY['Welcome. Browse if you must.', 'Everything here is, technically, for sale.', 'The hoodie is a hoodie. It will keep you warm. That is the entire pitch.']::text[], TRUE, 'shopkeeper', 'Keeps the shop, counts everything twice and finds most prices too high. Secretly restocks the things people like.', 'dry', '{"home":"shop","dawn":["shop"],"day":["shop","plaza","shop","pond"],"evening":["shop","pond"],"night":["home"]}'::jsonb, '[["Welcome. Browse if you must.","I keep the shelves in order of usefulness. Nobody has ever noticed.","[sad] I''ve started to take it personally."],["Selling your catches? The rarer ones fetch more.","That isn''t me being generous. It''s the rules.","[happy] I''m a little generous."],["[sleepy] Inventory day. I counted the hoodies twice.","There are the same number of hoodies. There are always the same number of hoodies."]]'::jsonb),
  ('curator', 'Odile', 'courtyard', TRUE, NULL, ARRAY['Every case in there is waiting for something you''ll find.', 'Did you see the dragonflies by the pond? Odonata. Lovely.', 'Bring me anything with wings. Or fins. Or a shell.']::text[], TRUE, 'museum_curator', 'The museum''s curator, labelling the empty cases until the club fills them. Knows the Latin name of every bug and says it anyway.', 'earnest', '{"home":"museum","dawn":["pond"],"day":["museum","pond","beach"],"evening":["museum","plaza"],"night":["museum","home"]}'::jsonb, '[["[happy] {name}! Found anything with wings lately?","The museum''s cases are waiting. The first of every find you bring me goes on show.","With a label. I write very good labels."],["Did you see the dragonflies by the pond? Odonata. Lovely things.","[surprised] They can fly backwards, you know. I think about that a lot."],["If you catch something you''ve never seen before, bring it to me before you sell it.","Once it''s in a case, it belongs to the whole club."]]'::jsonb),
  ('wharf-keeper', 'Bram', 'courtyard', TRUE, NULL, ARRAY['Tide''s turning. You can hear it if you listen.', 'The gulls are low today. Rain by supper, mark my words.', 'Boat''s ready whenever you want to go home.']::text[], TRUE, 'wharf_keeper', 'Minds the wharf and the boats, reads the tides off the posts and the weather off the gulls. Has a story for every knot.', 'playful', '{"home":"hq","dawn":["wharf"],"day":["wharf","beach","wharf","plaza"],"evening":["wharf","bench"],"night":["wharf","beach","wharf"]}'::jsonb, '[["Tide''s turning. You can hear it if you listen.","[happy] And the gulls are flying low. Rain by supper, mark my words."],["Boat''s ready whenever you want to go home.","Your island''s out past the pier. Small, but the sunsets are all yours."],["[surprised] Caught anything big yet?","Best fishing''s off the end of the wharf at dawn. Don''t tell anyone I told you."]]'::jsonb),
  ('oracle-keeper', 'Sable', 'courtyard', TRUE, NULL, ARRAY['The crystal is quiet today. It''s listening.', 'Which way will you grow? Ask the temple.', 'Stars are just old light. So are good friends.']::text[], TRUE, 'oracle_keeper', 'Keeps the Oracle temple and its crystal. Answers questions with better questions, and stays up to watch the stars from the temple steps.', 'earnest', '{"home":"oracle","dawn":["oracle"],"day":["oracle","pond","oracle"],"evening":["oracle","pond"],"night":["oracle","home"]}'::jsonb, '[["The crystal is quiet today. It''s listening.","What would you ask it, if you knew it would answer?"],["Which way will you grow, {name}? The temple can help you see it.","[happy] Not decide. Only see. The deciding is yours."],["Stars are just old light. So are good friends.","[sleepy] I was up late on the temple steps again. Clear skies."]]'::jsonb),
  ('crafter', 'Pim', 'courtyard', TRUE, NULL, ARRAY['Found a perfectly good plank on the beach. Perfectly good!', 'Bring me wood and I''ll show you a trick.', 'Measure twice, glue once.']::text[], TRUE, 'workshop_crafter', 'Tinkers at the HQ workbench and combs the beach for driftwood and bottles. Never without a pencil behind one ear.', 'playful', '{"home":"hq","dawn":["home"],"day":["hq","beach","path","plaza"],"evening":["plaza","hq"],"night":["hq","plaza","home"]}'::jsonb, '[["[happy] Found a perfectly good plank on the beach. Perfectly good!","Bring me some wood and I''ll show you a trick at the workbench."],["Measure twice, glue once. That''s the whole secret.","[surprised] Well. Most of it. The rest is snacks."],["Bottles wash up on the beach sometimes.","Some have notes in them. Some have recipes. Keep your eyes open."]]'::jsonb),
  ('juniper', 'Juniper', 'courtyard', TRUE, NULL, ARRAY['@morning Morning laps! Want to race to the pier?', 'Stretch first. Trust me.', 'The sand''s firmest right by the water.']::text[], TRUE, 'villager', 'Up before the sun to run the beach and stretch on the sand. Knows every shortcut on the island.', 'playful', '{"home":"hq","dawn":["beach","path"],"day":["pond","plaza","beach"],"evening":["plaza","beach"],"night":["beach","home"]}'::jsonb, '[["@morning [happy] Morning laps! Want to race to the pier?","Kidding. Mostly. Stretch first, trust me."],["The sand''s firmest right by the water.","[happy] Best place on the island for a sprint. Try it!"],["[sleepy] I''ve been up since dawn. Is it lunch yet?","No? Then one more lap."]]'::jsonb),
  ('marlo', 'Marlo', 'courtyard', TRUE, NULL, ARRAY['Hold still, you''re in the shot. Kidding. Mostly.', 'The pond looks different every hour.', 'I''m out of the green pencil again.']::text[], TRUE, 'villager', 'Sketches the island from the benches, a page a day. Has drawn HQ forty times and isn''t happy with any of them.', 'warm', '{"home":"hq","day":["bench","pond","museum"],"evening":["beach","bench"],"night":["pond","plaza","home"]}'::jsonb, '[["[happy] Hold still, you''re in the shot.","Kidding. Mostly. You do make a good shape for a sketch."],["I''ve drawn HQ forty times now.","[sad] I''m not happy with any of them. That roof has a mind of its own."],["The pond looks different every hour.","I''m out of the green pencil again. If you find one, it''s mine."]]'::jsonb),
  ('nell', 'Nell', 'courtyard', TRUE, NULL, ARRAY['See that one? I named it after the founders.', 'The fireflies came out early tonight.', 'Mornings are a rumour.']::text[], TRUE, 'villager', 'A night owl who sleeps in, then watches the stars from the bench under the lamp. Names the constellations after club members.', 'warm', '{"home":"hq","dawn":["home"],"day":["home","plaza","oracle"],"evening":["beach","bench"],"night":["bench","beach","bench"]}'::jsonb, '[["I named a star after the founders. The bright one over HQ, once it''s dark.","[happy] The fainter ones are for everyone who joined after. There''s room for plenty more."],["[sleepy] Mornings are a rumour. I''m told they''re nice.","The island''s best after dark anyway. The fireflies come out by the water."],["If you can''t sleep, come and find me at the lamp bench.","I''ll show you the constellation that looks like a fishing rod."]]'::jsonb)
ON CONFLICT (slug) DO NOTHING;
UPDATE npc_personas SET post = 'villager', bio = 'The island''s first resident and its historian. Remembers everyone''s first week and will tell the club''s story to anyone who sits still.', tone = 'warm', schedule = '{"home":"hq","dawn":["home"],"day":["path","plaza","bench","pond"],"evening":["plaza","pond"],"night":["plaza","home"]}'::jsonb WHERE slug = 'mayor' AND post IS NOT DISTINCT FROM NULL AND bio = '' AND tone IS NULL AND schedule = '{"day":"path"}'::jsonb;
UPDATE npc_personas SET post = 'shopkeeper', bio = 'Keeps the shop, counts everything twice and finds most prices too high. Secretly restocks the things people like.', tone = 'dry', schedule = '{"home":"shop","dawn":["shop"],"day":["shop","plaza","shop","pond"],"evening":["shop","pond"],"night":["home"]}'::jsonb WHERE slug = 'shopkeeper' AND post IS NOT DISTINCT FROM 'shopkeeper' AND bio = '' AND tone IS NULL AND schedule = '{"day":"shop"}'::jsonb;
