-- The rename. Her name, then the one text column of hers that could name her (none of the seeded lines do).
UPDATE npc_personas
   SET display_name = 'Alice',
       bio = replace(bio, 'Wren', 'Alice')
 WHERE slug = 'wren' AND display_name = 'Wren';

-- The settle-in chapter, which sends you back to her at HQ (20261017010000_hq_onboarding_copy).
UPDATE quest_chapters
   SET step_copy = jsonb_set(step_copy, '{report_hq,label}', '"Report back to Alice at HQ"')
 WHERE slug = 'settle-in'
   AND step_copy #>> '{report_hq,label}' = 'Report back to Wren at HQ';

UPDATE quest_chapters
   SET summary = 'Make your first catch and donate it to the museum, then report back to Alice at HQ.'
 WHERE slug = 'settle-in'
   AND summary = 'Make your first catch and donate it to the museum, then report back to Wren at HQ.';
